-- Onda 1 (segurança P0): remove acesso ANON das policies que estavam com USING(true)/WITH CHECK(true)
-- targetando o role {public}. Troca o role para {authenticated}, preservando USING/CHECK intactos.
-- Comportamento para usuários logados é idêntico; apenas o role anon (chave pública) perde acesso.
-- Reversível: ALTER POLICY ... TO public.

-- estoque / movimentação / catálogo operacional
ALTER POLICY "Acesso público total a estoque" ON public.estoque TO authenticated;
ALTER POLICY "Acesso público total a movimentações" ON public.movimentacoes TO authenticated;
ALTER POLICY "Acesso público total a anexos de movimentação" ON public.movimentacao_anexos TO authenticated;
ALTER POLICY "Acesso público total a alertas" ON public.alertas_estoque TO authenticated;
ALTER POLICY "Acesso público total a categorias" ON public.categorias TO authenticated;
ALTER POLICY "Acesso público total a setores" ON public.setores TO authenticated;
ALTER POLICY "Acesso público total a perdas" ON public.perdas TO authenticated;
ALTER POLICY "Acesso completo a produtos para todos os usuários" ON public.produtos TO authenticated;
ALTER POLICY "Allow all authenticated users" ON public.produtos_master TO authenticated;
ALTER POLICY "plv_select_all" ON public.produto_loja_visibility TO authenticated;

-- requisições
ALTER POLICY "Acesso público total a requisições" ON public.requisicoes TO authenticated;
ALTER POLICY "Acesso público total a itens de requisições" ON public.requisicoes_itens TO authenticated;

-- identidade / privilégio (remove anon; gating por role fica como refino da Onda 5)
ALTER POLICY "Acesso público total a usuários" ON public.usuarios TO authenticated;
ALTER POLICY "Acesso público total a user_admins" ON public.user_admins TO authenticated;

-- financeiro
ALTER POLICY "cofre_transferencias_insert" ON public.cofre_transferencias TO authenticated;
ALTER POLICY "cofre_transferencias_select" ON public.cofre_transferencias TO authenticated;
ALTER POLICY "Users can view all invoice notes" ON public.notas_fiscais TO authenticated;
ALTER POLICY "Users can view all invoice items" ON public.itens_nota_fiscal TO authenticated;
ALTER POLICY "Enable read access for all users" ON public.orcamentos_gerados TO authenticated;

-- sessões de conferência / separação digital (estavam totalmente abertas a anon)
ALTER POLICY "Users can view all session items" ON public.active_session_items TO authenticated;
ALTER POLICY "Users can create items in any active session" ON public.active_session_items TO authenticated;
ALTER POLICY "Users can update items in any active session" ON public.active_session_items TO authenticated;
ALTER POLICY "Users can delete items from any active session" ON public.active_session_items TO authenticated;
ALTER POLICY "Users can view all active sessions" ON public.active_sessions TO authenticated;
ALTER POLICY "Users can update any active session" ON public.active_sessions TO authenticated;
ALTER POLICY "Users can view digital separation items" ON public.digital_separation_items TO authenticated;
ALTER POLICY "Users can create digital separation items" ON public.digital_separation_items TO authenticated;
ALTER POLICY "Users can update digital separation items" ON public.digital_separation_items TO authenticated;
ALTER POLICY "Users can delete digital separation items" ON public.digital_separation_items TO authenticated;
ALTER POLICY "Users can view digital separation users" ON public.digital_separation_users TO authenticated;
ALTER POLICY "Users can create digital separation users" ON public.digital_separation_users TO authenticated;
ALTER POLICY "Users can update digital separation users" ON public.digital_separation_users TO authenticated;
ALTER POLICY "Users can delete digital separation users" ON public.digital_separation_users TO authenticated;
ALTER POLICY "Users can view digital separations" ON public.digital_separations TO authenticated;
