get_page_produtos: async (supabase: SupabaseClient, args: any) => {
    let query = supabase.from('produtos')
        .select(`
                id, nome, unidade_medida, categoria_id, preco_unitario, setor, foto_url, codigo_barras,
                categoria:categorias(nome)
            `)
        .limit(50)

    if (args.name) query = query.ilike('nome', `%${args.name}%`)

    const { data, error } = await query
    if (error) throw error
    return JSON.stringify(data)
